// src/components/DungeonMaster/Tabs/BattleTab.tsx
import React, { useState } from 'react';
import { DMViewProps } from "../../../types/game";
import StatGauges from '../../Player/StatGauges';
import { Plus, Minus } from 'lucide-react';
import { useCombatActions } from '../../../actions/combatActions';


interface BattleTabProps extends DMViewProps {}

export function BattleTab({ gameState, onGameStateChange, room, isRoomCreator }: BattleTabProps) {
  // Track selected initiative side before combat starts
  const [selectedInitiative, setSelectedInitiative] = useState<'party' | 'enemies'>('party');
  
  const isInCombat = gameState.combat?.isActive ?? false;
  const currentTurn = gameState.combat?.currentTurn ?? 0;
  const initiativeSide = gameState.combat?.initiativeSide ?? 'party';

  // Get combat actions
  const combatActions = useCombatActions(room, gameState, onGameStateChange, isRoomCreator);

  // Handle battle start
  const handleBattleStart = () => {
    combatActions.startCombat(selectedInitiative);
  };
  const handleNextTurn = () => {
    combatActions.nextTurn();
  };

  const handlePreviousTurn = () => {
    combatActions.previousTurn();
  };
  return (
    <div className="grid h-full w-full" style={{
      gridTemplateRows: '1fr 9fr',
      gap: '1rem',
      padding: '1rem',
    }}>
      {/* Row 1: Battle Controls */}
      <div className="grid grid-cols-3 gap-4 items-center">
        {/* Players Initiative Button */}
        <button
          onClick={() => !isInCombat && setSelectedInitiative('party')}
          disabled={isInCombat}
          className={`h-full rounded-lg border-2 transition-colors ${
            (isInCombat ? initiativeSide : selectedInitiative) === 'party'
              ? 'bg-blue-600 text-white border-blue-700'
              : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
          } ${isInCombat ? 'opacity-75 cursor-not-allowed' : ''}`}
        >
          Players
        </button>

        {/* Turn Counter */}
        <div className="flex items-center justify-center gap-4">
          {!isInCombat ? (
            <button 
              onClick={handleBattleStart}
              className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors"
            >
              Battle
            </button>
          ) : (
            <>
              <button
                onClick={handlePreviousTurn}
                disabled={currentTurn <= 1}
                className={`p-2 rounded-full hover:bg-gray-100 transition-colors ${
                  currentTurn <= 1 ? 'opacity-50 cursor-not-allowed' : ''
                }`}
                aria-label="Previous Turn"
              >
                <Minus size={24} />
              </button>
              <div className="text-2xl font-bold min-w-[100px] text-center">
                Turn {currentTurn}
              </div>
              <button
                onClick={handleNextTurn}
                className="p-2 rounded-full hover:bg-gray-100 transition-colors"
                aria-label="Next Turn"
              >
                <Plus size={24} />
              </button>
            </>
          )}
        </div>

        {/* Enemies Initiative Button */}
        <button
          onClick={() => !isInCombat && setSelectedInitiative('enemies')}
          disabled={isInCombat}
          className={`h-full rounded-lg border-2 transition-colors ${
            (isInCombat ? initiativeSide : selectedInitiative) === 'enemies'
              ? 'bg-red-600 text-white border-red-700'
              : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
          } ${isInCombat ? 'opacity-75 cursor-not-allowed' : ''}`}
        >
          Enemies
        </button>
      </div>

      {/* Row 2: Combatants */}
      <div className="grid grid-cols-2 gap-4">
        {/* Party List */}
        <div className="border rounded-lg p-4 overflow-y-auto">
          <h2 className="text-xl font-bold mb-4">Party Members</h2>
          <div className="space-y-4">
            {gameState.party.map(character => (
              <div key={character.id} className="border rounded-lg p-4">
                <h3 className="font-bold mb-2">{character.name}</h3>
                <StatGauges
                  character={character}
                  editable={true}
                  gameState={gameState}
                  onGameStateChange={onGameStateChange}
                />
              </div>
            ))}
          </div>
        </div>

        {/* Field Entities List */}
        <div className="border rounded-lg p-4 overflow-y-auto">
          <h2 className="text-xl font-bold mb-4">Field Enemies</h2>
          <div className="space-y-4">
            {gameState.field.map(entity => (
              <div key={entity.id} className="border rounded-lg p-4">
                <h3 className="font-bold mb-2">{entity.name}</h3>
                <StatGauges
                  character={entity}
                  editable={true}
                  gameState={gameState}
                  onGameStateChange={onGameStateChange}
                />
              </div>
            ))}
            {gameState.field.length === 0 && (
              <div className="text-gray-500 text-center py-8">
                No enemies on the field
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}