import React, { useState, useCallback } from 'react';
import { imageManager } from '../../../services/ImageManager';
import type { GameImage, GameState } from '../../../types/game';
import type { Room } from 'trystero/torrent';
import { useImageSync } from '../../../hooks/useImageSync';
import { EnvironmentDisplay } from '../../shared/ImageDisplay';
import { Upload } from 'lucide-react';

interface VisualsTabProps {
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  room?: Room;
  isRoomCreator: boolean;
}

export function VisualsTab({ gameState, onGameStateChange, room, isRoomCreator }: VisualsTabProps) {
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string>('');
  const [uploadProgress, setUploadProgress] = useState<string>('');
  useImageSync(room, isRoomCreator);

  const handleSetEnvironmentImage = async (imageId: string) => {
    if (isRoomCreator && (window as any).broadcastImage) {
      try {
        await (window as any).broadcastImage(imageId);
      } catch (err) {
        console.error('Failed to broadcast image:', err);
        setError('Failed to send image to players');
        return;
      }
    }

    onGameStateChange({
      ...gameState,
      display: {
        ...gameState.display,
        environmentImageId: imageId
      }
    });
  };

  const handleSetFocusImage = async (imageId: string) => {
    if (isRoomCreator && (window as any).broadcastImage) {
      try {
        await (window as any).broadcastImage(imageId);
      } catch (err) {
        console.error('Failed to broadcast image:', err);
        setError('Failed to send image to players');
        return;
      }
    }

    onGameStateChange({
      ...gameState,
      display: {
        ...gameState.display,
        focusImageId: imageId,
        showFocusImage: true
      }
    });
  };

  const handleToggleFocusImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    onGameStateChange({
      ...gameState,
      display: {
        ...gameState.display,
        showFocusImage: e.target.checked
      }
    });
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setIsUploading(true);
    setError('');
    
    const newImages: GameImage[] = [];
    const totalFiles = files.length;

    try {
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        setUploadProgress(`Uploading image ${i + 1} of ${totalFiles}`);
        
        try {
          const newImage = await imageManager.addImage(file);
          newImages.push(newImage);
        } catch (err) {
          console.error(`Failed to upload image ${file.name}:`, err);
          setError(prev => prev + `\nFailed to upload ${file.name}`);
        }
      }

      if (newImages.length > 0) {
        onGameStateChange({
          ...gameState,
          globalCollections: {
            ...gameState.globalCollections,
            images: [...gameState.globalCollections.images, ...newImages]
          }
        });
      }

    } catch (err) {
      console.error('Failed during batch upload:', err);
      setError('Some images failed to upload. Please try again.');
    } finally {
      setIsUploading(false);
      setUploadProgress('');
      e.target.value = '';
    }
  };

  const ImageSelector = useCallback(({ 
    images,
    selectedId,
    onSelect,
    title
  }: {
    images: GameImage[],
    selectedId?: string,
    onSelect: (id: string) => void,
    title: string
  }) => (
    <div className="h-full flex flex-col bg-white rounded-lg shadow-sm">
      <div className="p-4 border-b">
        <h3 className="text-lg font-semibold">{title}</h3>
      </div>
      <div className="flex-1 overflow-y-auto p-4">
        <div className="grid grid-cols-3 gap-4">
          {images.map((image) => (
            <div
              key={image.id}
              onClick={() => onSelect(image.id)}
              className={`
                aspect-square cursor-pointer rounded-lg overflow-hidden border-2 transition-all
                ${selectedId === image.id ? 'border-blue-500 shadow-lg' : 'border-transparent hover:border-blue-200'}
              `}
            >
              <div className="relative w-full h-full">
                <img
                  src={image.thumbnail}
                  alt={image.name}
                  className="w-full h-full object-cover"
                />
                <div className={`
                  absolute inset-0 flex items-center justify-center
                  bg-black bg-opacity-0 hover:bg-opacity-30 transition-opacity
                `}>
                  <span className="text-white opacity-0 hover:opacity-100 text-sm text-center px-2">
                    {selectedId === image.id ? 'Current Selection' : 'Select Image'}
                  </span>
                </div>
                <div className="absolute bottom-0 left-0 right-0 bg-black bg-opacity-50 p-2">
                  <div className="text-white text-xs truncate">{image.name}</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  ), []);

  return (
    <div className="h-full w-full" style={{
      display: 'grid',
      gridTemplateColumns: '3fr 4fr 3fr',
      gap: '1.5vh',
      padding: '1.5vh 1.5vh 1.5vh 1.5vh',
    }}>
      {/* Environment Images Column */}
      <div className="min-h-0 bg-white rounded-lg shadow-sm">
        <ImageSelector
          images={gameState.globalCollections.images}
          selectedId={gameState.display.environmentImageId}
          onSelect={handleSetEnvironmentImage}
          title="Environment Images"
        />
      </div>

      {/* Scene Preview Column */}
<div className="min-h-0 bg-white rounded-lg shadow-sm">
  <div className="h-full flex flex-col">
    {/* Header with Toggle */}
    <div className="p-4 border-b flex justify-between items-center">
      <h3 className="text-lg font-semibold">Scene Preview</h3>
      <label className="flex items-center space-x-2">
        <input
          type="checkbox"
          checked={gameState.display.showFocusImage}
          onChange={handleToggleFocusImage}
          className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
        />
        <span className="text-sm">Show Focus Image</span>
      </label>
    </div>

    {/* Upload Button */}
    <div className="p-4 border-b">
      <label className="flex items-center justify-center gap-2 cursor-pointer w-full py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md transition-colors">
        <Upload className="w-5 h-5" />
        <span className="font-medium">Upload Images</span>
        <input
          type="file"
          accept="image/*"
          multiple
          onChange={handleFileSelect}
          disabled={isUploading}
          className="hidden"
        />
      </label>
      {isUploading && (
        <div className="mt-2 text-center text-sm text-blue-600">
          {uploadProgress}
        </div>
      )}
      {error && (
        <div className="mt-2 text-center text-sm text-red-500">
          {error}
        </div>
      )}
    </div>

    {/* Preview Display */}
    <div className="flex-1 flex items-center justify-center p-4">
      <div className="w-full aspect-video">
        <EnvironmentDisplay gameState={gameState} />
      </div>
    </div>

    {/* Bottom Buttons */}
    <div className="p-4 border-t grid grid-cols-2 gap-4">
      <button
        onClick={() => {
          onGameStateChange({
            ...gameState,
            display: {
              ...gameState.display,
              environmentImageId: undefined,
              focusImageId: undefined,
              showFocusImage: false
            }
          });
        }}
        className="py-2 px-4 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-md transition-colors"
      >
        Reset Scene
      </button>
      <button
        onClick={() => {
          // TODO: Implement submit functionality
          console.log('Scene submitted:', gameState.display);
        }}
        className="py-2 px-4 bg-green-600 hover:bg-green-700 text-white rounded-md transition-colors"
      >
        Submit Scene
      </button>
    </div>
  </div>
</div>

      {/* Focus Images Column */}
      <div className="min-h-0 bg-white rounded-lg shadow-sm">
        <ImageSelector
          images={gameState.globalCollections.images}
          selectedId={gameState.display.focusImageId}
          onSelect={handleSetFocusImage}
          title="Focus Images"
        />
      </div>

      
    </div>
  );
}