import React, { useState, useEffect } from 'react';
import { InventorySlot } from '../../types/game';
import { Scroll } from 'lucide-react';
import { imageManager } from '../../services/ImageManager';

interface InventoryPanelProps {
  inventory: InventorySlot[];
  onClose: () => void;
  onUseItem?: (itemId: string) => void;
  onEquipItem?: (itemId: string) => void;
}

export function InventoryPanel({
  inventory,
  onClose,
  onUseItem,
  onEquipItem
}: InventoryPanelProps) {
  // Add state for item images
  const [itemImages, setItemImages] = useState<Record<string, string>>({});

  // Effect to load images for items
  useEffect(() => {
    const loadItemImages = async () => {
      const newItemImages: Record<string, string> = {};
      
      for (const [item] of inventory) {
        if (item.image) {
          // First try to get the thumbnail which is faster
          const thumbnail = imageManager.getThumbnail(item.image);
          if (thumbnail) {
            newItemImages[item.id] = thumbnail;
            continue;
          }

          // If no thumbnail, try to get the full image
          try {
            const file = await imageManager.getImage(item.image);
            if (file) {
              const reader = new FileReader();
              reader.onload = () => {
                setItemImages(prev => ({
                  ...prev,
                  [item.id]: reader.result as string
                }));
              };
              reader.readAsDataURL(file);
            }
          } catch (error) {
            console.error(`Failed to load image for item ${item.id}:`, error);
          }
        }
      }
      
      setItemImages(newItemImages);
    };

    loadItemImages();
  }, [inventory]);

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col">
        <div className="flex justify-between items-center mb-4">
          <div className="flex items-center gap-2">
            <Scroll className="w-5 h-5" />
            <h2 className="text-xl font-bold">Inventory</h2>
          </div>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700"
          >
            ×
          </button>
        </div>

        {inventory.length === 0 ? (
          <div className="flex-1 flex items-center justify-center text-gray-500">
            Inventory is empty
          </div>
        ) : (
          <div className="flex-1 overflow-auto">
            <div className="grid gap-4">
              {inventory.map(([item, count]) => (
                <div
                  key={item.id}
                  className="flex p-4 border rounded-lg bg-white shadow-sm"
                >
                  <div className="flex-shrink-0 mr-4">
                    {item.image && itemImages[item.id] ? (
                      <img
                        src={itemImages[item.id]}
                        alt={item.name}
                        className="w-16 h-16 object-cover rounded-md bg-gray-100"
                      />
                    ) : (
                      <div className="w-16 h-16 bg-gray-100 rounded-md flex items-center justify-center">
                        <span className="text-gray-400 text-xs">No image</span>
                      </div>
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex justify-between items-start">
                      <div>
                        <h4 className="font-medium">{item.name}</h4>
                        <p className="text-sm text-gray-600 mt-1">{item.description}</p>
                        <div className="text-sm text-gray-500 mt-1">
                          Quantity: {count}
                        </div>
                      </div>
                      <div className="flex gap-2">
                        {item.isEquippable && onEquipItem && (
                          <button
                            onClick={() => onEquipItem(item.id)}
                            className="px-3 py-1 text-sm bg-blue-50 text-blue-600 rounded-md hover:bg-blue-100"
                          >
                            Equip
                          </button>
                        )}
                        {onUseItem && item.uses !== undefined && (
                          <button
                            onClick={() => onUseItem(item.id)}
                            className="px-3 py-1 text-sm bg-green-50 text-green-600 rounded-md hover:bg-green-100"
                          >
                            Use
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}