import React, { useState } from 'react';
import { EntityEditor } from '../EntityEditor';
import { Entity, GameState } from '../../../types/game';
import StatGauges from '../../Player/StatGauges';

interface EncounterTabProps {
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
}

export function EncounterTab({ gameState, onGameStateChange }: EncounterTabProps) {
  const [showEditor, setShowEditor] = useState(false);
  const [selectedEntityId, setSelectedEntityId] = useState<string | null>(null);
  const [showSpawnedEntities, setShowSpawnedEntities] = useState(true);

  // Get the selected entity either from the catalog or field
  const selectedEntity = selectedEntityId
    ? (gameState.globalCollections.entities.find(e => e.id === selectedEntityId) ||
       gameState.field.find(e => e.id === selectedEntityId))
    : undefined;

  const handleAddEntity = (entity: Omit<Entity, 'id'>) => {
    const newId = crypto.randomUUID();
    const newEntity: Entity = {
      ...entity,
      id: newId,
    };

    onGameStateChange({
      ...gameState,
      globalCollections: {
        ...gameState.globalCollections,
        entities: [...gameState.globalCollections.entities, newEntity]
      }
    });
  };

  const handleUpdateEntity = (id: string, updates: Partial<Entity>) => {
    // Check if entity is in catalog or field and update accordingly
    const isInCatalog = gameState.globalCollections.entities.some(e => e.id === id);
    
    if (isInCatalog) {
      onGameStateChange({
        ...gameState,
        globalCollections: {
          ...gameState.globalCollections,
          entities: gameState.globalCollections.entities.map(entity =>
            entity.id === id ? { ...entity, ...updates } : entity
          )
        }
      });
    } else {
      onGameStateChange({
        ...gameState,
        field: gameState.field.map(entity =>
          entity.id === id ? { ...entity, ...updates } : entity
        )
      });
    }
  };

  const handleDeleteEntity = (id: string) => {
    // Remove entity from both catalog and field
    onGameStateChange({
      ...gameState,
      globalCollections: {
        ...gameState.globalCollections,
        entities: gameState.globalCollections.entities.filter(e => e.id !== id)
      },
      field: gameState.field.filter(e => e.id !== id)
    });
  };

  const handleSpawnEntity = (catalogEntityId: string) => {
    const entityToSpawn = gameState.globalCollections.entities.find(e => e.id === catalogEntityId);
    if (!entityToSpawn) return;

    // Create a new instance of the entity with a new ID
    const spawnedEntity: Entity = {
      ...entityToSpawn,
      id: crypto.randomUUID(),
    };

    onGameStateChange({
      ...gameState,
      field: [...gameState.field, spawnedEntity]
    });
  };

  const handleDespawnEntity = (fieldEntityId: string) => {
    onGameStateChange({
      ...gameState,
      field: gameState.field.filter(e => e.id !== fieldEntityId)
    });
  };

  return (
    <div className="">
      {/* Entity Catalog Section */}
      <div className="bg-white rounded-lg p-4 shadow">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold">Entity Catalog</h2>
          <button
            onClick={() => {
              setSelectedEntityId(null);
              setShowEditor(true);
            }}
            className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700"
          >
            Create New Entity
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {gameState.globalCollections.entities.map(entity => (
            <div
              key={entity.id}
              className="border rounded-lg p-4 hover:shadow-md transition-shadow"
            >
              <div className="flex justify-between items-start mb-2">
                <h3 className="font-bold">{entity.name}</h3>
                <div className="space-x-2">
                  <button
                    onClick={() => {
                      setSelectedEntityId(entity.id);
                      setShowEditor(true);
                    }}
                    className="text-blue-600 hover:text-blue-800"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => handleSpawnEntity(entity.id)}
                    className="text-green-600 hover:text-green-800"
                  >
                    Spawn
                  </button>
                </div>
              </div>
              <p className="text-sm text-gray-600 mb-2">{entity.description}</p>
              <div className="text-sm">
              <StatGauges
                  character={entity}
                  editable={true}
                  gameState={gameState}
                  onGameStateChange={onGameStateChange}
                />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Field Entities Section */}
      <div className="bg-white rounded-lg p-4 shadow">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold">
            Field Entities
            <span className="ml-2 text-sm text-gray-500">
              ({gameState.field.length} active)
            </span>
          </h2>
          <button
            onClick={() => setShowSpawnedEntities(!showSpawnedEntities)}
            className="text-blue-600 hover:text-blue-800"
          >
            {showSpawnedEntities ? 'Hide' : 'Show'}
          </button>
        </div>

        {showSpawnedEntities && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {gameState.field.map(entity => (
              <div
                key={entity.id}
                className="border rounded-lg p-4 hover:shadow-md transition-shadow"
              >
                <div className="flex justify-between items-start mb-2">
                  <h3 className="font-bold">{entity.name}</h3>
                  <div className="space-x-2">
                    <button
                      onClick={() => {
                        setSelectedEntityId(entity.id);
                        setShowEditor(true);
                      }}
                      className="text-blue-600 hover:text-blue-800"
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => handleDespawnEntity(entity.id)}
                      className="text-red-600 hover:text-red-800"
                    >
                      Despawn
                    </button>
                  </div>
                </div>
                <p className="text-sm text-gray-600 mb-2">{entity.description}</p>
                <div className="text-sm">
                <StatGauges
                  character={entity}
                  editable={true}
                  gameState={gameState}
                  onGameStateChange={onGameStateChange}
                />
                </div>
              </div>
            ))}

            {gameState.field.length === 0 && (
              <div className="col-span-full text-center py-8 text-gray-500">
                No entities currently in the field
              </div>
            )}
          </div>
        )}
      </div>

      {/* Entity Editor Modal */}
      {showEditor && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold">
                {selectedEntity ? 'Edit Entity' : 'Create Entity'}
              </h3>
            </div>
            
            <EntityEditor
              entity={selectedEntity}
              onSave={handleAddEntity}
              onUpdate={handleUpdateEntity}
              onDelete={handleDeleteEntity}
              onClose={() => {
                setShowEditor(false);
                setSelectedEntityId(null);
              }}
            />
          </div>
        </div>
      )}
    </div>
  );
}