// src/actions/skillActions.ts
import type { Room } from 'trystero/torrent';
import type { 
  GameState, 
  Skill, 
  InteractiveActor, 
  Character, 
  Entity 
} from '../types/game';
import { selfId } from 'trystero';

export const SkillActions = {
  CREATE: 'skillCreate',
  UPDATE: 'skillUpdt',  // Shortened to stay under 12 bytes
  DELETE: 'skillDel',   // Shortened to stay under 12 bytes
  USE: 'skillUse',
  LEARN: 'skillLearn',  // For adding a skill to an actor
  FORGET: 'skillForget' // For removing a skill from an actor
} as const;

interface SkillCreatePayload {
  skill: Omit<Skill, 'id'>;
  playerId: string;
}

interface SkillUpdatePayload {
  id: string;
  updates: Partial<Skill>;
  playerId: string;
}

interface SkillDeletePayload {
  id: string;
  playerId: string;
}

interface SkillUsePayload {
  skillId: string;
  actorId: string;
  targetId?: string;  // Optional target of the skill
  playerId: string;
}

interface SkillLearnPayload {
  skillId: string;
  actorId: string;
  playerId: string;
}

interface SkillForgetPayload {
  skillId: string;
  actorId: string;
  playerId: string;
}

// Helper function to find an actor in either party or entities
function findActor(gameState: GameState, actorId: string): InteractiveActor | undefined {
  const partyMember = gameState.party.find(char => char.id === actorId);
  if (partyMember) return partyMember;
  return gameState.entities.find(entity => entity.id === actorId);
}
function canUseSkill(skill: Skill): boolean {
  // If skill has no uses limit, it can always be used
  if (skill.uses === undefined) return true;
  // If it has uses limit but no usesLeft value, initialize it
  if (skill.usesLeft === undefined) return skill.uses > 0;
  // Otherwise check the remaining uses
  return skill.usesLeft > 0;
}
// Helper function to update an actor's skills
function updateActorSkills(
  actor: InteractiveActor,
  skillId: string,
  operation: 'add' | 'remove',
  globalSkills: Skill[]
): InteractiveActor {
  if (operation === 'remove') {
    return {
      ...actor,
      skills: actor.skills.filter(skill => skill.id !== skillId)
    };
  }
  
  if (operation === 'add') {
    const skillToAdd = globalSkills.find(skill => skill.id === skillId);
    if (!skillToAdd || actor.skills.some(skill => skill.id === skillId)) {
      return actor;
    }
    
    return {
      ...actor,
      skills: [...actor.skills, { ...skillToAdd }]
    };
  }

  return actor;
}

export function setupSkillActions(
  room: Room,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  const [sendSkillCreate, getSkillCreate] = room.makeAction<SkillCreatePayload>(SkillActions.CREATE);
  const [sendSkillUpdate, getSkillUpdate] = room.makeAction<SkillUpdatePayload>(SkillActions.UPDATE);
  const [sendSkillDelete, getSkillDelete] = room.makeAction<SkillDeletePayload>(SkillActions.DELETE);
  const [sendSkillUse, getSkillUse] = room.makeAction<SkillUsePayload>(SkillActions.USE);
  const [sendSkillLearn, getSkillLearn] = room.makeAction<SkillLearnPayload>(SkillActions.LEARN);
  const [sendSkillForget, getSkillForget] = room.makeAction<SkillForgetPayload>(SkillActions.FORGET);

  if (isRoomCreator) {
    // Handle skill creation
    getSkillCreate(({ skill, playerId }, peerId) => {
      console.log(`Player ${playerId} requested to create skill:`, skill);
      const newId = crypto.randomUUID();
      const newSkill: Skill = { ...skill, id: newId };
      
      onGameStateChange({
        ...gameState,
        globalCollections: {
          ...gameState.globalCollections,
          skills: [...gameState.globalCollections.skills, newSkill]
        }
      });
    });

    // Handle skill updates
    getSkillUpdate(({ id, updates, playerId }, peerId) => {
      console.log(`Player ${playerId} requested to update skill ${id}:`, updates);
      onGameStateChange({
        ...gameState,
        globalCollections: {
          ...gameState.globalCollections,
          skills: gameState.globalCollections.skills.map(skill =>
            skill.id === id ? { ...skill, ...updates } : skill
          )
        }
      });
    });

    // Handle skill deletion
    getSkillDelete(({ id, playerId }, peerId) => {
      console.log(`Player ${playerId} requested to delete skill ${id}`);
      onGameStateChange({
        ...gameState,
        globalCollections: {
          ...gameState.globalCollections,
          skills: gameState.globalCollections.skills.filter(skill => skill.id !== id)
        }
      });
    });

    // Handle skill usage
    getSkillUse(({ skillId, actorId, targetId, playerId }, peerId) => {
      console.log(`Player ${playerId} requested to use skill ${skillId} by ${actorId} on ${targetId || 'no target'}`);
      
      const actor = findActor(gameState, actorId);
      if (!actor) return;
    
      const skill = actor.skills.find(s => s.id === skillId);
      if (!skill) return;
      
      // Check if skill can be used
      if (skill.uses !== undefined) {
        const currentUsesLeft = skill.usesLeft ?? skill.uses;
        if (currentUsesLeft <= 0) return;
      }
    
      let updatedParty = [...gameState.party];
      let updatedEntities = [...gameState.entities];
    
      // Update the actor who used the skill
      const updatedActor: InteractiveActor = {
        ...actor,
        skills: actor.skills.map(s => {
          if (s.id === skillId) {
            // If skill has no uses limit, return as is
            if (s.uses === undefined) return s;
            // If it has uses but no usesLeft, initialize it from uses
            const currentUsesLeft = s.usesLeft ?? s.uses;
            return { 
              ...s, 
              usesLeft: Math.max(0, currentUsesLeft - 1)
            };
          }
          return s;
        })
      };
    
      if ('equipment' in updatedActor) {
        updatedParty = updatedParty.map(char =>
          char.id === actorId ? updatedActor as Character : char
        );
      } else {
        updatedEntities = updatedEntities.map(entity =>
          entity.id === actorId ? updatedActor as Entity : entity
        );
      }
    
      // Here you might want to add effects on the target based on the skill
      if (targetId) {
        const target = findActor(gameState, targetId);
        if (target) {
          const updatedTarget: InteractiveActor = {
            ...target,
            hp: Math.max(0, target.hp - skill.damage)
          };
    
          if ('equipment' in updatedTarget) {
            updatedParty = updatedParty.map(char =>
              char.id === targetId ? updatedTarget as Character : char
            );
          } else {
            updatedEntities = updatedEntities.map(entity =>
              entity.id === targetId ? updatedTarget as Entity : entity
            );
          }
        }
      }
    
      onGameStateChange({
        ...gameState,
        party: updatedParty,
        entities: updatedEntities
      });
    });

    // Handle learning a skill
    getSkillLearn(({ skillId, actorId, playerId }, peerId) => {
      console.log(`Player ${playerId} requested actor ${actorId} to learn skill ${skillId}`);
      
      const actor = findActor(gameState, actorId);
      if (!actor) return;

      let updatedParty = [...gameState.party];
      let updatedEntities = [...gameState.entities];

      const updatedActor = updateActorSkills(
        actor,
        skillId,
        'add',
        gameState.globalCollections.skills
      );

      if ('equipment' in updatedActor) {
        updatedParty = updatedParty.map(char =>
          char.id === actorId ? updatedActor as Character : char
        );
      } else {
        updatedEntities = updatedEntities.map(entity =>
          entity.id === actorId ? updatedActor as Entity : entity
        );
      }

      onGameStateChange({
        ...gameState,
        party: updatedParty,
        entities: updatedEntities
      });
    });

    // Handle forgetting a skill
    getSkillForget(({ skillId, actorId, playerId }, peerId) => {
      console.log(`Player ${playerId} requested actor ${actorId} to forget skill ${skillId}`);
      
      const actor = findActor(gameState, actorId);
      if (!actor) return;

      let updatedParty = [...gameState.party];
      let updatedEntities = [...gameState.entities];

      const updatedActor = updateActorSkills(
        actor,
        skillId,
        'remove',
        gameState.globalCollections.skills
      );

      if ('equipment' in updatedActor) {
        updatedParty = updatedParty.map(char =>
          char.id === actorId ? updatedActor as Character : char
        );
      } else {
        updatedEntities = updatedEntities.map(entity =>
          entity.id === actorId ? updatedActor as Entity : entity
        );
      }

      onGameStateChange({
        ...gameState,
        party: updatedParty,
        entities: updatedEntities
      });
    });
  }

  // Return functions for both DM and players
  return {
    createSkill: (skill: Omit<Skill, 'id'>) => {
      console.log(`Sending skill creation request from ${selfId}`);
      return sendSkillCreate({ skill, playerId: selfId });
    },

    updateSkill: (id: string, updates: Partial<Skill>) => {
      console.log(`Sending skill update request for ${id} from ${selfId}`);
      return sendSkillUpdate({ id, updates, playerId: selfId });
    },

    deleteSkill: (id: string) => {
      console.log(`Sending skill deletion request for ${id} from ${selfId}`);
      return sendSkillDelete({ id, playerId: selfId });
    },

    useSkill: (skillId: string, actorId: string, targetId?: string) => {
      console.log(`Sending skill use request from ${selfId}`);
      return sendSkillUse({ skillId, actorId, targetId, playerId: selfId });
    },

    learnSkill: (skillId: string, actorId: string) => {
      console.log(`Sending skill learn request from ${selfId}`);
      return sendSkillLearn({ skillId, actorId, playerId: selfId });
    },

    forgetSkill: (skillId: string, actorId: string) => {
      console.log(`Sending skill forget request from ${selfId}`);
      return sendSkillForget({ skillId, actorId, playerId: selfId });
    }
  };
}

// Hook to use skill actions
export function useSkillActions(
  room: Room | undefined,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  if (!room) {
    return {
      createSkill: () => Promise.resolve(),
      updateSkill: () => Promise.resolve(),
      deleteSkill: () => Promise.resolve(),
      useSkill: () => Promise.resolve(),
      learnSkill: () => Promise.resolve(),
      forgetSkill: () => Promise.resolve()
    };
  }

  return setupSkillActions(room, gameState, onGameStateChange, isRoomCreator);
}