import React, { useState, useEffect } from 'react';
import { Plus, ChevronsRight } from 'lucide-react';
import { imageManager } from '../../services/ImageManager';

interface BasicObjectViewProps {
  name: string;
  imageId?: string;  // Changed from imageUrl to imageId
  size?: 'sm' | 'md' | 'lg' | 'xl';
  className?: string;
  border?: {
    color?: string;
    width?: number;
  };
  action?: {
    onClick: () => void;
    icon: 'plus' | 'arrow';
    disabled?: boolean;
  };
  onClick?: () => void;
}

const sizeClasses = {
  sm: 'w-28 h-28',
  md: 'w-36 h-36',
  lg: 'w-44 h-44',
  xl: 'w-52 h-52'
};

const nameSizeClasses = {
  sm: 'text-sm px-3',
  md: 'text-base px-4',
  lg: 'text-lg px-6',
  xl: 'text-xl px-8'
};

const buttonSizeClasses = {
  sm: 'w-10 h-10',
  md: 'w-12 h-12',
  lg: 'w-14 h-14',
  xl: 'w-16 h-16'
};

const iconSizeClasses = {
  sm: 'w-5 h-5',
  md: 'w-6 h-6',
  lg: 'w-7 h-7',
  xl: 'w-8 h-8'
};

const BasicObjectView = ({ 
  name, 
  imageId, 
  size = 'md',
  className = '',
  border,
  action,
  onClick
}: BasicObjectViewProps) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  useEffect(() => {
    let mounted = true;

    const loadImage = async () => {
      if (!imageId) return;

      // First try to get the thumbnail which is faster
      const thumbnail = imageManager.getThumbnail(imageId);
      if (thumbnail && mounted) {
        setImageUrl(thumbnail);
      }

      try {
        const imageData = await imageManager.getImage(imageId);
        if (imageData && mounted) {
          const url = URL.createObjectURL(imageData);
          setImageUrl(url);
          return () => URL.revokeObjectURL(url);
        }
      } catch (error) {
        console.error('Failed to load image:', error);
      }
    };

    loadImage();

    return () => {
      mounted = false;
    };
  }, [imageId]);

  const borderStyles = border ? {
    borderColor: border.color,
    borderWidth: border.width ? `${border.width}px` : '2px'
  } : undefined;

  return (
    <div className="relative inline-block">
      <div 
        onClick={onClick}
        className={`
          relative
          ${sizeClasses[size]}
          rounded-lg
          border-2
          border-grey
          dark:border-offwhite
          overflow-hidden
          transition-all
          ${onClick ? 'cursor-pointer hover:scale-105' : ''}
          ${className}
        `}
        style={borderStyles}
      >
        {imageUrl ? (
          <>
            <img 
              src={imageUrl}
              alt={name}
              className="w-full h-full object-cover"
            />
            <div className="
              absolute 
              top-0 
              left-0 
              right-0
              px-2 
              py-1
              bg-grey/60
              dark:bg-offwhite/60
            ">
              <p className="
                text-offwhite
                dark:text-grey
                text-md
                truncate
                font-medium
              ">
                {name}
              </p>
            </div>
          </>
        ) : (
          <div className="
            w-full 
            h-full 
            bg-gradient-to-br 
            from-blue 
            dark:from-cyan 
            to-transparent
            flex 
            items-center 
            justify-center
          ">
            <p className={`
              text-offwhite
              dark:text-grey
              font-medium
              text-center
              ${nameSizeClasses[size]}
              break-words
            `}>
              {name}
            </p>
          </div>
        )}
      </div>

      {action && (
        <div className="absolute w-full h-full top-0 left-0 pointer-events-none">
          <button
            onClick={action.onClick}
            disabled={action.disabled}
            className={`
              absolute
              ${buttonSizeClasses[size]}
              rotate-45
              border-blue
              dark:border-cyan
              bg-offwhite
              dark:bg-grey
              text-blue
              dark:text-cyan
              rounded
              flex
              items-center
              justify-center
              hover:border-4
              disabled:border-grey
              disabled:text-grey
              dark:disabled:border-offwhite
              dark:disabled:text-offwhite
              disabled:cursor-not-allowed
              transition-opacity
              border-2
              pointer-events-auto
              left-[100%]
              top-[100%]
              -translate-x-1/2
              -translate-y-1/2
            `}
          >
            <div className={`-rotate-45 ${iconSizeClasses[size]}`}>
              {action.icon === 'plus' ? (
                <Plus strokeWidth={3} />
              ) : (
                <ChevronsRight strokeWidth={3} />
              )}
            </div>
          </button>
        </div>
      )}
    </div>
  );
};

export default BasicObjectView;