import React, { useState } from 'react';
import type { PlayerViewProps } from '../../types/game';
import { CharacterSheet } from './CharacterSheet';
import StatGauges from './StatGauges';
import { InventoryPanel } from './InventoryPanel';
import { EquipmentPanel } from './EquipmentPanel';
import { SkillsPanel } from './SkillsPanel';
import { CharacterControls } from './CharacterControls';
import { EnvironmentDisplay } from '../shared/ImageDisplay';
import { CoolTabs, CoolTabsList, CoolTabsTrigger, CoolTabsContent } from '../ui/cooltabs';

export function SafeView({ gameState, onGameStateChange, playerId, onCharacterSelect, room }: PlayerViewProps) {
  const [showInventory, setShowInventory] = useState(false);
  const [showEquipment, setShowEquipment] = useState(false);
  const [showSkills, setShowSkills] = useState(false);
  
  // Find the selected character
  const selectedCharacter = gameState.party.find(c => c.playerId === playerId);
  
  // Filter out the selected character from the party members display
  const otherPartyMembers = gameState.party.filter(c => c.playerId !== playerId);

  return (
    <div className="grid h-[88vh] w-full" style={{
      gridTemplateColumns: '4fr 6fr',
      gridTemplateRows: '3fr 7fr',
      gap: '1vh',
      padding: '1vh 1vh 1vh 1vh',
    }}>
      {/* Column 1, Row 1: Character Sheet & Stats */}
      <div className=" rounded-lg shadow p-4 min-h-0">
        <div className="h-full overflow-auto">
          {selectedCharacter && (
            <div className="space-y-4">
              <CharacterSheet character={selectedCharacter} />
              <StatGauges
                character={selectedCharacter}
                editable={true}
                gameState={gameState}
                onGameStateChange={onGameStateChange}
                showSideLabels={false}  // Disable side labels
                size="medium"  // Or "small" or "large"
              />
            </div>
          )}
        </div>
      </div>

      {/* Column 2, Row 1: Party Members (excluding selected character) */}
      <div className=" rounded-lg shadow p-4 min-h-0">
        <div className="h-full overflow-auto">
          <h2 className="text-xl font-bold mb-4">Other Party Members</h2>
          {otherPartyMembers.length === 0 ? (
            <p className="text-gray-500 text-center">No other party members</p>
          ) : (
            <div className="grid gap-4">
              {otherPartyMembers.map(character => (
                <div key={character.id} className="border rounded-lg p-4">
                  <CharacterSheet character={character} />
                  <StatGauges 
                    character={character}
                    editable={false}
                    gameState={gameState}
                    onGameStateChange={onGameStateChange}
                  />
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Column 1, Row 2: Control Panel with Tabs */}
      <div className=" rounded-lg shadow p-4 min-h-0">
        <div className="h-full flex flex-col ">
          <CoolTabs defaultValue="equipment" className="flex-1 flex flex-col">
            <CoolTabsList>
              <CoolTabsTrigger value="equipment" tabType="equipment" />
              <CoolTabsTrigger value="inventory" tabType="inventory" />
              <CoolTabsTrigger value="skills" tabType="skills" />
              <CoolTabsTrigger value="settings" tabType="settings" />
            </CoolTabsList>

            <CoolTabsContent value="settings" className="flex-1 overflow-auto">
              {selectedCharacter && (
                <CharacterControls
                  onOpenInventory={() => setShowInventory(true)}
                  onOpenEquipment={() => setShowEquipment(true)}
                  onOpenSkills={() => setShowSkills(true)}
                />
              )}
            </CoolTabsContent>

            <CoolTabsContent value="inventory" className="flex-1 overflow-auto">
              {selectedCharacter && (
                <div className="p-4">
                  <h3 className="text-lg font-bold mb-4">Inventory</h3>
                  <div className="grid gap-2">
                    {selectedCharacter.inventory.map(([item, count]) => (
                      <div key={item.id} className="border rounded p-2">
                        <div className="font-medium">{item.name}</div>
                        <div className="text-sm text-gray-600">Quantity: {count}</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </CoolTabsContent>

            <CoolTabsContent value="equipment" className="flex-1 overflow-auto">
              {selectedCharacter && (
                <div className="p-4">
                  <h3 className="text-lg font-bold mb-4">Equipment</h3>
                  <div className="grid gap-2">
                    {selectedCharacter.equipment.map(item => (
                      <div key={item.id} className="border rounded p-2">
                        <div className="font-medium">{item.name}</div>
                        <div className="text-sm text-gray-600">{item.description}</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </CoolTabsContent>

            <CoolTabsContent value="skills" className="flex-1 overflow-auto">
              {selectedCharacter && (
                <div className="p-4">
                  <h3 className="text-lg font-bold mb-4">Skills</h3>
                  <div className="grid gap-2">
                    {selectedCharacter.skills.map(skill => (
                      <div key={skill.id} className="border rounded p-2">
                        <div className="font-medium">{skill.name}</div>
                        <div className="text-sm text-gray-600">
                          Damage: {skill.damage} | SP Cost: {skill.spCost}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </CoolTabsContent>
          </CoolTabs>
        </div>

        {/* Modal Panels */}
        {showInventory && selectedCharacter && (
          <InventoryPanel
            inventory={selectedCharacter.inventory}
            onClose={() => setShowInventory(false)}
          />
        )}

        {showEquipment && selectedCharacter && (
          <EquipmentPanel
            equipment={selectedCharacter.equipment}
            onClose={() => setShowEquipment(false)}
          />
        )}

        {showSkills && selectedCharacter && (
          <SkillsPanel
            skills={selectedCharacter.skills}
            onClose={() => setShowSkills(false)}
          />
        )}
      </div>

      {/* Column 2, Row 2: Image Display */}
      <div className=" rounded-lg shadow p-4 min-h-0">
        <div className="h-full overflow-auto">
          <EnvironmentDisplay gameState={gameState} />
        </div>
      </div>
    </div>
  );
}