import type { Room } from 'trystero/torrent';
import { type GameState } from '../types/game';

export const CombatActions = {
  START: 'combatStart',
  END: 'combatEnd',
  NEXT_TURN: 'combatNext',
  PREV_TURN: 'combatPrev',
  REGEN_SP: 'spRegen',
} as const;


export function setupCombatActions(
  room: Room,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  // If not room creator (DM), return empty functions
  if (!isRoomCreator) {
    return {
      startCombat: () => {},
      endCombat: () => {},
      nextTurn: () => {},
      previousTurn: () => {},
    };
  }

  // Return functions for DM
  return {
    startCombat: (initialSide: 'party' | 'enemies') => {
      console.log(`DM starting combat with ${initialSide} initiative`);
      onGameStateChange({
        ...gameState,
        combat: {
          isActive: true,
          currentTurn: 1,
          initiativeSide: initialSide
        }
      });
    },

    endCombat: () => {
      console.log('DM ending combat');
      onGameStateChange({
        ...gameState,
        combat: {
          isActive: false,
          currentTurn: 0,
          initiativeSide: 'party'
        }
      });
    },

    nextTurn: () => {
      if (!gameState.combat?.isActive) return;
      
      console.log('DM advancing to next turn');
      onGameStateChange({
        ...gameState,
        combat: {
          ...gameState.combat,
          currentTurn: gameState.combat.currentTurn + 1,
          initiativeSide: gameState.combat.initiativeSide === 'party' ? 'enemies' : 'party'
        }
      });
    },

    previousTurn: () => {
      if (!gameState.combat?.isActive || gameState.combat.currentTurn <= 1) return;
      
      console.log('DM going to previous turn');
      onGameStateChange({
        ...gameState,
        combat: {
          ...gameState.combat,
          currentTurn: gameState.combat.currentTurn - 1,
          initiativeSide: gameState.combat.initiativeSide === 'party' ? 'enemies' : 'party'
        }
      });
    }
  };
}

// Hook to use combat actions
export function useCombatActions(
  room: Room | undefined,
  gameState: GameState,
  onGameStateChange: (newState: GameState) => void,
  isRoomCreator: boolean
) {
  if (!room) {
    return {
      startCombat: () => {},
      endCombat: () => {},
      nextTurn: () => {},
      previousTurn: () => {}
    };
  }

  return setupCombatActions(room, gameState, onGameStateChange, isRoomCreator);
}