import { useCallback, useRef, useState } from 'react';
import { selfId } from 'trystero';
import type { Room } from '../types/room';
import { GameState, GameImage, SerializableSaveState, initialGameState, Item, Character, Entity } from '../types/game';
import { imageManager } from '../services/ImageManager';
import { roomManager } from '../services/RoomManager';

interface ImageTransitData {
  data: string;
  originalId: string;
  thumbnail: string;
}

interface TransitGameImage extends Omit<GameImage, 'thumbnail'> {
  data?: string;
  originalId?: string;
  thumbnail: string;
}

interface TransitCharacter extends Character {
  imageData?: ImageTransitData;
}

interface TransitItem extends Omit<Item, 'image'> {
  image?: string;
  imageData?: ImageTransitData;
}

interface TransitEntity extends Omit<Entity, 'image'> {
  image?: string;
  imageData?: ImageTransitData;
}

interface TransitGameState extends Omit<GameState, 'party'> {
  party: TransitCharacter[];
  globalCollections: {
    items: TransitItem[];
    skills: GameState['globalCollections']['skills'];
    statusEffects: GameState['globalCollections']['statusEffects'];
    images: TransitGameImage[];
    entities: TransitEntity[];
  };
  field: TransitEntity[];
}
interface TransitSaveState extends Omit<SerializableSaveState, 'gameState'> {
  gameState: TransitGameState;
  lastModified: number;
  roomCreator: string;
}

export function usePeerSync(isRoomCreator: boolean) {
  const [gameState, setGameState] = useState<GameState>(initialGameState);
  const gameStateRef = useRef<GameState>(initialGameState);
  const sendGameStateRef = useRef<(state: SerializableSaveState, target?: string | string[]) => void>();

  const broadcastGameState = useCallback(async () => {
    if (isRoomCreator && sendGameStateRef.current) {
      const transitState = await prepareStateForTransit(gameStateRef.current);
      sendGameStateRef.current({
        gameState: transitState,
        lastModified: Date.now(),
        roomCreator: selfId
      });
    }
  }, [isRoomCreator]);

  const handlePeerDisconnect = useCallback((peerId: string) => {
    if (isRoomCreator) {
      const currentState = gameStateRef.current;
      const updatedParty = currentState.party.map(character => 
        character.playerId === peerId 
          ? { ...character, playerId: undefined }
          : character
      );

      const newState = {
        ...currentState,
        party: updatedParty
      };

      gameStateRef.current = newState;
      setGameState(newState);
      broadcastGameState();
    }
  }, [broadcastGameState, isRoomCreator]);

  const prepareStateForTransit = async (state: GameState): Promise<TransitGameState> => {
    // Process and filter images
    const processedImages = await Promise.all(
      state.globalCollections.images.map(async (img) => {
        try {
          const file = await imageManager.getImage(img.id);
          if (file) {
            const dataUrl = await new Promise<string>((resolve) => {
              const reader = new FileReader();
              reader.onloadend = () => resolve(reader.result as string);
              reader.readAsDataURL(file);
            });
            const thumbnail = imageManager.getThumbnail(img.id);
            
            if (!thumbnail) {
              console.warn(`Missing thumbnail for image ${img.id}, skipping...`);
              return null;
            }
  
            const transitImage: TransitGameImage = {
              ...img,
              data: dataUrl,
              thumbnail,
              originalId: img.id
            };
            return transitImage;
          }
        } catch (err) {
          console.error(`Failed to prepare image ${img.id} for transit:`, err);
        }
        return null;
      })
    );
  
    // Filter out nulls with type guard
    const filteredImages: TransitGameImage[] = processedImages.filter(
      (img): img is TransitGameImage => img !== null
    );
  
    const transitState: TransitGameState = {
      ...state,
      globalCollections: {
        ...state.globalCollections,
        images: filteredImages,
        items: await Promise.all(
          state.globalCollections.items.map(async (item) => {
            if (item.image) {
              try {
                const file = await imageManager.getImage(item.image);
                if (file) {
                  const dataUrl = await new Promise<string>((resolve) => {
                    const reader = new FileReader();
                    reader.onloadend = () => resolve(reader.result as string);
                    reader.readAsDataURL(file);
                  });
                  const thumbnail = imageManager.getThumbnail(item.image);
                  
                  if (!thumbnail) {
                    console.warn(`Missing thumbnail for item image ${item.image}, skipping image data...`);
                    return item;
                  }
  
                  return {
                    ...item,
                    imageData: {
                      data: dataUrl,
                      thumbnail,
                      originalId: item.image
                    }
                  } satisfies TransitItem;
                }
              } catch (err) {
                console.error(`Failed to prepare item image ${item.image} for transit:`, err);
              }
            }
            return item;
          })
        )
      }
    };
  
    // Process character images similarly
    transitState.party = await Promise.all(
      state.party.map(async (char) => {
        if (char.image) {
          try {
            const file = await imageManager.getImage(char.image);
            if (file) {
              const dataUrl = await new Promise<string>((resolve) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result as string);
                reader.readAsDataURL(file);
              });
              const thumbnail = imageManager.getThumbnail(char.image);
              
              if (!thumbnail) {
                console.warn(`Missing thumbnail for character image ${char.image}, skipping image data...`);
                return char;
              }
  
              return {
                ...char,
                image: dataUrl,
                imageData: {
                  data: dataUrl,
                  thumbnail,
                  originalId: char.image
                }
              };
            }
          } catch (err) {
            console.error(`Failed to prepare character image for transit:`, err);
          }
        }
        return char;
      })
    );
    transitState.globalCollections.entities = await Promise.all(
      state.globalCollections.entities.map(async (entity) => {
        if (entity.image) {
          try {
            const file = await imageManager.getImage(entity.image);
            if (file) {
              const dataUrl = await new Promise<string>((resolve) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result as string);
                reader.readAsDataURL(file);
              });
              const thumbnail = imageManager.getThumbnail(entity.image);
              
              if (!thumbnail) {
                console.warn(`Missing thumbnail for entity image ${entity.image}, skipping image data...`);
                return entity;
              }
  
              return {
                ...entity,
                imageData: {
                  data: dataUrl,
                  thumbnail,
                  originalId: entity.image
                }
              } satisfies TransitEntity;
            }
          } catch (err) {
            console.error(`Failed to prepare entity image ${entity.image} for transit:`, err);
          }
        }
        return entity;
      })
    );
  
    // Process entities in the field
    transitState.field = await Promise.all(
      state.field.map(async (entity) => {
        if (entity.image) {
          try {
            const file = await imageManager.getImage(entity.image);
            if (file) {
              const dataUrl = await new Promise<string>((resolve) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result as string);
                reader.readAsDataURL(file);
              });
              const thumbnail = imageManager.getThumbnail(entity.image);
              
              if (!thumbnail) {
                console.warn(`Missing thumbnail for field entity image ${entity.image}, skipping image data...`);
                return entity;
              }
  
              return {
                ...entity,
                imageData: {
                  data: dataUrl,
                  thumbnail,
                  originalId: entity.image
                }
              } satisfies TransitEntity;
            }
          } catch (err) {
            console.error(`Failed to prepare field entity image ${entity.image} for transit:`, err);
          }
        }
        return entity;
      })
    );
  
    return transitState;
  };

  const processReceivedState = async (receivedState: TransitGameState): Promise<GameState> => {
    const processedState = { ...receivedState };

    // Process character images
    for (const character of processedState.party) {
      if (character.image?.startsWith('data:') && 'imageData' in character) {
        try {
          const response = await fetch(character.image);
          const blob = await response.blob();
          const file = new File([blob], `character-${character.imageData?.originalId || character.id}.png`, {
            type: 'image/png'
          });

          if (character.imageData?.originalId && character.imageData?.thumbnail) {
            await imageManager.addReceivedImage(file, {
              id: character.imageData.originalId,
              name: file.name,
              description: `Character image for ${character.name}`,
              createdAt: Date.now(),
              size: file.size,
              type: file.type,
              thumbnail: character.imageData.thumbnail
            });
            character.image = character.imageData.originalId;
          } else {
            const imageData = await imageManager.addImage(file);
            character.image = imageData.id;
          }
        } catch (error) {
          console.error('Failed to process character image:', error);
          character.image = undefined;
        }
      }
    }

    // Process items with images
    processedState.globalCollections.items = await Promise.all(
      processedState.globalCollections.items.map(async (item) => {
        if ('imageData' in item && item.imageData?.data) {
          try {
            const response = await fetch(item.imageData.data);
            const blob = await response.blob();
            const file = new File([blob], `item-${item.imageData.originalId}.png`, {
              type: 'image/png'
            });

            if (item.imageData.originalId && item.imageData.thumbnail) {
              await imageManager.addReceivedImage(file, {
                id: item.imageData.originalId,
                name: file.name,
                description: `Item image for ${item.name}`,
                createdAt: Date.now(),
                size: file.size,
                type: file.type,
                thumbnail: item.imageData.thumbnail
              });
              return {
                ...item,
                image: item.imageData.originalId
              };
            } else {
              const imageData = await imageManager.addImage(file);
              return {
                ...item,
                image: imageData.id
              };
            }
          } catch (error) {
            console.error('Failed to process item image:', error);
            return {
              ...item,
              image: undefined
            };
          }
        }
        return item;
      })
    );

    // Process global collection images
    const processedImages = await Promise.all(
      processedState.globalCollections.images.map(async (image) => {
        if ('data' in image && image.data && image.originalId) {
          try {
            const response = await fetch(image.data);
            const blob = await response.blob();
            const file = new File([blob], image.name, {
              type: image.type
            });

            await imageManager.addReceivedImage(file, {
              id: image.originalId,
              name: image.name,
              description: image.description,
              createdAt: image.createdAt,
              size: file.size,
              type: file.type,
              thumbnail: image.thumbnail
            });

            const { data, ...imageWithoutData } = image;
            return {
              ...imageWithoutData,
              id: image.originalId
            };
          } catch (error) {
            console.error('Failed to process collection image:', error);
            const { data, ...imageWithoutData } = image;
            return imageWithoutData;
          }
        }
        return image;
      })
    );
      processedState.globalCollections.entities = await Promise.all(
        processedState.globalCollections.entities.map(async (entity) => {
          if ('imageData' in entity && entity.imageData?.data) {
            try {
              const response = await fetch(entity.imageData.data);
              const blob = await response.blob();
              const file = new File([blob], `entity-${entity.imageData.originalId}.png`, {
                type: 'image/png'
              });
    
              if (entity.imageData.originalId && entity.imageData.thumbnail) {
                await imageManager.addReceivedImage(file, {
                  id: entity.imageData.originalId,
                  name: file.name,
                  description: `Entity image for ${entity.name}`,
                  createdAt: Date.now(),
                  size: file.size,
                  type: file.type,
                  thumbnail: entity.imageData.thumbnail
                });
                return {
                  ...entity,
                  image: entity.imageData.originalId
                };
              } else {
                const imageData = await imageManager.addImage(file);
                return {
                  ...entity,
                  image: imageData.id
                };
              }
            } catch (error) {
              console.error('Failed to process entity image:', error);
              return {
                ...entity,
                image: undefined
              };
            }
          }
          return entity;
        })
      );
    
      // Process entities in the field
      processedState.field = await Promise.all(
        processedState.field.map(async (entity) => {
          if ('imageData' in entity && entity.imageData?.data) {
            try {
              const response = await fetch(entity.imageData.data);
              const blob = await response.blob();
              const file = new File([blob], `field-entity-${entity.imageData.originalId}.png`, {
                type: 'image/png'
              });
    
              if (entity.imageData.originalId && entity.imageData.thumbnail) {
                await imageManager.addReceivedImage(file, {
                  id: entity.imageData.originalId,
                  name: file.name,
                  description: `Field entity image for ${entity.name}`,
                  createdAt: Date.now(),
                  size: file.size,
                  type: file.type,
                  thumbnail: entity.imageData.thumbnail
                });
                return {
                  ...entity,
                  image: entity.imageData.originalId
                };
              } else {
                const imageData = await imageManager.addImage(file);
                return {
                  ...entity,
                  image: imageData.id
                };
              }
            } catch (error) {
              console.error('Failed to process field entity image:', error);
              return {
                ...entity,
                image: undefined
              };
            }
          }
          return entity;
        })
    );
    
    processedState.globalCollections.images = processedImages;
    return processedState;
  };

  const handleGameStateChange = useCallback(async (newState: GameState) => {
    gameStateRef.current = newState;
    setGameState(newState);

    if (isRoomCreator && sendGameStateRef.current) {
      const transitState = await prepareStateForTransit(newState);
      sendGameStateRef.current({
        gameState: transitState,
        lastModified: Date.now(),
        roomCreator: selfId
      });
    }
  }, [isRoomCreator]);


  const initializePeerSync = useCallback((room: Room) => {
    const [sendGameState, getGameState] = room.makeAction<TransitSaveState>('gameState');
    const [requestGameState, getStateRequest] = room.makeAction<{ from: string }>('requestState');
    
    sendGameStateRef.current = sendGameState;

    getGameState(async (state, peerId) => {
      console.log('Received game state from:', peerId, state);
      const processedState = await processReceivedState(state.gameState);
      gameStateRef.current = processedState;
      setGameState(processedState);
    });

    getStateRequest(async (data, peerId) => {
      if (isRoomCreator && sendGameStateRef.current) {
        const transitState = await prepareStateForTransit(gameStateRef.current);
        sendGameStateRef.current({
          gameState: transitState,
          lastModified: Date.now(),
          roomCreator: selfId
        }, peerId);
      }
    });

    roomManager.events.on('peerDisconnected', handlePeerDisconnect);

    room.onPeerJoin(peerId => {
      if (!isRoomCreator) {
        requestGameState({ from: selfId }, peerId);
      } else {
        setTimeout(async () => {
          const transitState = await prepareStateForTransit(gameStateRef.current);
          sendGameState({
            gameState: transitState,
            lastModified: Date.now(),
            roomCreator: selfId
          }, peerId);
        }, 1000);
      }
    });

    return () => {
      roomManager.events.off('peerDisconnected', handlePeerDisconnect);
    };
  }, [isRoomCreator, handlePeerDisconnect]);

  return {
    gameState,
    setGameState,
    handleGameStateChange,
    broadcastGameState,
    initializePeerSync,
  };
}