import { useEffect, useRef } from 'react';
import type { Room } from 'trystero/torrent';
import { imageManager } from '../services/ImageManager';

interface ImageChunk {
  imageId: string;
  chunk: number[];
  index: number;
  total: number;
  metadata: {
    type: string;
    name: string;
    size: number;
    originalSize: number;  
    originalType: string;  
  };
  thumbnail: string;
}

const CHUNK_SIZE = 256 * 1024;
const PARALLEL_CHUNKS = 3;
const CHUNK_DELAY = 20;
const REQUEST_RETRY_DELAY = 2000;
const MAX_REQUEST_RETRIES = 3;

// Compression configuration
const COMPRESSION_QUALITY = 0.7;  // JPEG quality (0-1)
const MAX_DIMENSION = 2048;      // Maximum dimension for scaling

interface PendingRequest {
  imageId: string;
  retryCount: number;
  timeoutId?: NodeJS.Timeout;
  peerId?: string;
}

async function compressImage(file: File): Promise<File> {
  // Only compress images that would benefit from it
  if (!file.type.startsWith('image/') || file.type === 'image/gif' || file.size < 100000) {
    return file;
  }

  return new Promise((resolve, reject) => {
    const img = new Image();
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    img.onload = () => {
      // Calculate new dimensions while maintaining aspect ratio
      let width = img.width;
      let height = img.height;
      
      if (width > MAX_DIMENSION || height > MAX_DIMENSION) {
        if (width > height) {
          height = (height / width) * MAX_DIMENSION;
          width = MAX_DIMENSION;
        } else {
          width = (width / height) * MAX_DIMENSION;
          height = MAX_DIMENSION;
        }
      }

      canvas.width = width;
      canvas.height = height;

      if (!ctx) {
        reject(new Error('Failed to get canvas context'));
        return;
      }

      // Draw and compress
      ctx.drawImage(img, 0, 0, width, height);
      
      // Convert to JPEG with quality setting
      canvas.toBlob(
        (blob) => {
          if (!blob) {
            reject(new Error('Failed to compress image'));
            return;
          }
          resolve(new File([blob], file.name, { 
            type: 'image/jpeg',
            lastModified: file.lastModified 
          }));
        },
        'image/jpeg',
        COMPRESSION_QUALITY
      );
    };

    img.onerror = () => reject(new Error('Failed to load image for compression'));
    img.src = URL.createObjectURL(file);
  });
}

export function useImageSync(room: Room | undefined, isRoomCreator: boolean) {
  const pendingRequests = useRef(new Map<string, PendingRequest>());
  const chunkCache = useRef(new Map<string, Map<number, Uint8Array>>());
  const actionsInitialized = useRef(false);

  useEffect(() => {
    if (!room) return;

    console.log('Setting up image sync - isRoomCreator:', isRoomCreator);
    
    const actions = {
      chunk: room.makeAction<ImageChunk>('imageChunk'),
      request: room.makeAction<{ from: string; requestId: string }>('requestEnv'),
      response: room.makeAction<{ 
        imageId: string; 
        requestId: string; 
        success: boolean; 
        error?: string 
      }>('responseEnv')
    };

    const [sendImageChunk, getImageChunk] = actions.chunk;
    const [sendImageRequest, getImageRequest] = actions.request;
    const [sendImageResponse, getImageResponse] = actions.response;

    getImageChunk(async (chunk) => {
      const { imageId, index, total, metadata, thumbnail } = chunk;
      console.log(`Received chunk ${index + 1}/${total} for image ${imageId}`);
      
      try {
        if (!metadata?.type) throw new Error('Invalid image metadata');

        let imageChunks = chunkCache.current.get(imageId);
        if (!imageChunks) {
          imageChunks = new Map();
          chunkCache.current.set(imageId, imageChunks);
        }

        imageChunks.set(index, new Uint8Array(chunk.chunk));

        if (imageChunks.size === total) {
          console.log(`Reconstructing image ${imageId} from ${total} chunks`);
          
          const completeBuffer = new Uint8Array(metadata.size);
          let position = 0;

          for (let i = 0; i < total; i++) {
            const chunk = imageChunks.get(i);
            if (!chunk) throw new Error(`Missing chunk ${i}`);
            completeBuffer.set(chunk, position);
            position += chunk.length;
          }

          const file = new File([completeBuffer], metadata.name, { 
            type: metadata.type,
            lastModified: Date.now()
          });

          console.log(`Successfully reconstructed image ${imageId}, storing...`);

          await imageManager.addReceivedImage(file, {
            id: imageId,
            name: metadata.name,
            description: `Received image: ${metadata.name}`,
            createdAt: Date.now(),
            size: metadata.size,
            type: metadata.type,
            thumbnail
          });

          console.log(`Successfully stored image ${imageId}`);
          cleanupRequest(imageId);
        }
      } catch (error) {
        console.error(`Failed to process chunk ${index} for image ${imageId}:`, error);
        cleanupRequest(imageId);
      }
    });

    getImageResponse(async ({ imageId, requestId, success, error }) => {
      if (isRoomCreator) return;

      const request = pendingRequests.current.get(imageId);
      if (!request) {
        console.warn(`Received response for unknown request ${requestId}`);
        return;
      }

      if (!success) {
        console.error(`Image request ${requestId} failed:`, error);
        cleanupRequest(imageId);
        return;
      }

      console.log(`Image transfer starting for request ${requestId}`);
      if (request.timeoutId) {
        clearTimeout(request.timeoutId);
        request.timeoutId = undefined;
      }
    });

    if (isRoomCreator) {
      getImageRequest(async ({ from: imageId, requestId }, peerId) => {
        console.log(`DM received image request ${requestId} for image ${imageId} from peer ${peerId}`);
        
        try {
          const image = await imageManager.getImage(imageId);
          const imageData = await imageManager.getImageData(imageId);
          
          if (!image || !imageData) {
            console.error('DM could not find requested image:', imageId);
            await sendImageResponse({ 
              imageId, 
              requestId, 
              success: false, 
              error: 'Image not found' 
            }, peerId);
            return;
          }

          // Compress image before sending
          const compressedImage = await compressImage(image);
          console.log('Compression results:', {
            originalSize: image.size,
            compressedSize: compressedImage.size,
            reduction: ((image.size - compressedImage.size) / image.size * 100).toFixed(1) + '%'
          });

          await sendImageResponse({ 
            imageId, 
            requestId, 
            success: true 
          }, peerId);

          console.log(`DM starting compressed image transfer for request ${requestId}`);
          
          const buffer = await compressedImage.arrayBuffer();
          const chunksArray = new Uint8Array(buffer);
          const totalChunks = Math.ceil(chunksArray.length / CHUNK_SIZE);

          console.log(`Sending ${totalChunks} chunks for ${imageId} to ${peerId}`);

          for (let i = 0; i < totalChunks; i += PARALLEL_CHUNKS) {
            const batch = Array.from(
              { length: Math.min(PARALLEL_CHUNKS, totalChunks - i) },
              (_, index) => {
                const start = (i + index) * CHUNK_SIZE;
                const end = Math.min(start + CHUNK_SIZE, chunksArray.length);
                return {
                  index: i + index,
                  data: Array.from(chunksArray.slice(start, end))
                };
              }
            );

            await Promise.all(batch.map(chunk =>
              sendImageChunk({
                imageId,
                chunk: chunk.data,
                index: chunk.index,
                total: totalChunks,
                metadata: {
                  type: compressedImage.type,
                  name: image.name,
                  size: buffer.byteLength,
                  originalSize: image.size,
                  originalType: image.type
                },
                thumbnail: imageData.thumbnail
              }, peerId)
            ));

            await new Promise(resolve => setTimeout(resolve, CHUNK_DELAY));
          }

          console.log(`Completed sending image ${imageId} to peer ${peerId}`);
        } catch (err) {
          console.error('Failed to process image request:', err);
          await sendImageResponse({ 
            imageId, 
            requestId, 
            success: false, 
            error: err instanceof Error ? err.message : 'Unknown error' 
          }, peerId);
        }
      });
    }

    actionsInitialized.current = true;

    if (!isRoomCreator) {
      (window as any).requestImage = (imageId: string) => {
        if (pendingRequests.current.has(imageId)) {
          console.log(`Request already pending for ${imageId}`);
          return;
        }

        const requestId = crypto.randomUUID();
        console.log(`Requesting image ${imageId} (${requestId})`);
        
        const request: PendingRequest = {
          imageId,
          retryCount: 0,
          timeoutId: setTimeout(() => {
            retryRequest(imageId);
          }, REQUEST_RETRY_DELAY)
        };

        pendingRequests.current.set(imageId, request);
        sendImageRequest({ from: imageId, requestId });
      };
    }

    function cleanupRequest(imageId: string) {
      const request = pendingRequests.current.get(imageId);
      if (request?.timeoutId) {
        clearTimeout(request.timeoutId);
      }
      pendingRequests.current.delete(imageId);
      chunkCache.current.delete(imageId);
    }

    function retryRequest(imageId: string) {
      const request = pendingRequests.current.get(imageId);
      if (!request) return;

      if (request.retryCount >= MAX_REQUEST_RETRIES) {
        console.log(`Max retries reached for ${imageId}`);
        cleanupRequest(imageId);
        return;
      }

      request.retryCount++;
      const requestId = crypto.randomUUID();
      console.log(`Retry ${request.retryCount}/${MAX_REQUEST_RETRIES} for ${imageId}`);
      
      sendImageRequest({ from: imageId, requestId });

      request.timeoutId = setTimeout(() => {
        retryRequest(imageId);
      }, REQUEST_RETRY_DELAY);
    }

    return () => {
      actionsInitialized.current = false;
      pendingRequests.current.forEach(request => {
        if (request.timeoutId) {
          clearTimeout(request.timeoutId);
        }
      });
      pendingRequests.current.clear();
      chunkCache.current.clear();

      if (!isRoomCreator) {
        delete (window as any).requestImage;
      }
    };
  }, [room, isRoomCreator]);

  return actionsInitialized.current;
}